"use client"

/** @responsibility Renders a flow (Sankey) diagram — node bars, proportional ribbons, and labels — that fills its host's box, with hover emphasis and controllable link selection. Geometry comes from sankey-chart-layout. */

import * as React from "react"

import { cn } from "@/lib/utils"

import {
  computeSankeyLayout,
  sankeyCenterlinePath,
  sankeyRibbonPath,
  type SankeyAlign,
  type SankeyLayout,
  type SankeyLayoutLink,
  type SankeyLayoutNode,
} from "./sankey-chart-layout"

/** A flow endpoint. */
export interface SankeyChartNode {
  /** Unique id links refer to. */
  id: string
  /** Text shown beside the node bar. Defaults to the id. */
  label?: string
  /**
   * Optional CSS color for the bar and the ribbons leaving it. Omitted,
   * both draw in the neutral foreground wash.
   */
  color?: string
}

/** A weighted flow between two nodes. */
export interface SankeyChartLink {
  /**
   * Stable id for selection. Defaults to `${source}→${target}`, so parallel
   * links between the same pair need explicit ids.
   */
  id?: string
  source: string
  target: string
  value: number
}

/** Everything known about a node when a label or detail is rendered. */
export interface SankeyChartNodeContext {
  node: SankeyChartNode
  /** Flow through the node: max of incoming and outgoing sums. */
  value: number
  inValue: number
  outValue: number
  /** Zero-based column the node landed in. */
  column: number
  columnCount: number
  /** Sum of node values in this node's column. */
  columnTotal: number
}

/** Properties accepted by the SankeyChart. */
export interface SankeyChartProps
  extends Omit<React.ComponentProps<"div">, "onSelect"> {
  nodes: readonly SankeyChartNode[]
  links: readonly SankeyChartLink[]
  /** Pixel width of each node bar. */
  nodeWidth?: number
  /** Minimum vertical gap between bars in a column. */
  nodeGap?: number
  /** Ribbon bend, 0 (straight taper) to 1 (full S curve). */
  curvature?: number
  /** Column placement for nodes without outgoing flow. */
  align?: SankeyAlign
  /**
   * Width of the label gutters reserved left and right of the diagram.
   * Zero hides the labels entirely.
   */
  labelWidth?: number
  /** Formats a flow value wherever one is shown. */
  formatValue?: (value: number) => string
  /**
   * Second label line under a node's name — defaults to the formatted node
   * value. Return null to drop the line for that node.
   */
  renderNodeDetail?: (context: SankeyChartNodeContext) => React.ReactNode
  /** Accessible name for a link. Defaults to "source to target, value". */
  linkLabel?: (link: SankeyChartLink) => string
  /** Controlled selected link id; null for no selection. */
  selectedLinkId?: string | null
  /** Initial selection when uncontrolled. */
  defaultSelectedLinkId?: string | null
  /** Called when a link is selected (click, Enter, Space) or cleared. */
  onSelectedLinkChange?: (
    linkId: string | null,
    link: SankeyChartLink | null,
  ) => void
}

/** Emphasis a bar, ribbon, or label is drawn with. */
type SankeyEmphasis = "rest" | "active" | "dim"

function linkIdOf(link: SankeyChartLink): string {
  return link.id ?? `${link.source}→${link.target}`
}

function useMeasuredBox(ref: React.RefObject<HTMLElement | null>) {
  const [box, setBox] = React.useState<{ width: number; height: number } | null>(
    null,
  )
  React.useLayoutEffect(() => {
    const element = ref.current
    if (!element) return
    const observer = new ResizeObserver((entries) => {
      const rect = entries[entries.length - 1].contentRect
      const width = Math.round(rect.width)
      const height = Math.round(rect.height)
      setBox((previous) =>
        previous && previous.width === width && previous.height === height
          ? previous
          : { width, height },
      )
    })
    observer.observe(element)
    return () => observer.disconnect()
  }, [ref])
  return box
}

const RIBBON_CLASSES = cn(
  "cursor-pointer fill-[var(--nessa-sankey-color,var(--muted-foreground))] opacity-15 outline-none",
  "transition-opacity [transition-duration:var(--nessa-motion-duration-fast)] [transition-timing-function:var(--nessa-motion-easing-standard)] motion-reduce:transition-none",
  "hover:opacity-35",
  "data-[emphasis=active]:opacity-55 data-[emphasis=dim]:opacity-[0.06] data-[emphasis=dim]:hover:opacity-25",
  "focus-visible:stroke-ring focus-visible:stroke-2",
)

const BAR_CLASSES = cn(
  "fill-[var(--nessa-sankey-color,var(--muted-foreground))] opacity-45",
  "transition-opacity [transition-duration:var(--nessa-motion-duration-fast)] [transition-timing-function:var(--nessa-motion-easing-standard)] motion-reduce:transition-none",
  "data-[emphasis=active]:fill-[var(--nessa-sankey-color,var(--foreground))] data-[emphasis=active]:opacity-100 data-[emphasis=dim]:opacity-30",
)

const LABEL_CLASSES = cn(
  "pointer-events-none absolute flex -translate-y-1/2 flex-col justify-center",
  "nessa-text-3 leading-tight text-muted-foreground",
  "transition-colors [transition-duration:var(--nessa-motion-duration-fast)] [transition-timing-function:var(--nessa-motion-easing-standard)] motion-reduce:transition-none",
  "data-[emphasis=active]:font-medium data-[emphasis=active]:text-foreground",
)

/**
 * A flow diagram: node bars in columns joined by ribbons whose thickness is
 * proportional to the flow they carry. The chart fills the box the host
 * gives it on both axes. Ribbons are keyboard-focusable buttons; hovering a
 * ribbon or bar emphasizes the connected flow, and clicking (or Enter or
 * Space) selects a link, drawing its centerline. Selection is
 * host-controllable through `selectedLinkId`; Escape or a background click
 * clears it.
 */
function SankeyChart({
  nodes,
  links,
  nodeWidth = 12,
  nodeGap = 12,
  curvature = 0.7,
  align = "justify",
  labelWidth = 132,
  formatValue = (value) => String(value),
  renderNodeDetail,
  linkLabel,
  selectedLinkId,
  defaultSelectedLinkId = null,
  onSelectedLinkChange,
  className,
  ...props
}: SankeyChartProps) {
  const plotRef = React.useRef<HTMLDivElement>(null)
  const box = useMeasuredBox(plotRef)

  const [hovered, setHovered] = React.useState<
    { kind: "link"; id: string } | { kind: "node"; id: string } | null
  >(null)
  const [uncontrolledSelection, setUncontrolledSelection] = React.useState(
    defaultSelectedLinkId,
  )
  const selection =
    selectedLinkId !== undefined ? selectedLinkId : uncontrolledSelection

  const nodeById = React.useMemo(
    () => new Map(nodes.map((node) => [node.id, node])),
    [nodes],
  )

  const layout: SankeyLayout | null = React.useMemo(() => {
    if (!box || box.width <= 0 || box.height <= 0) return null
    return computeSankeyLayout({
      nodes,
      links,
      width: box.width,
      height: box.height,
      nodeWidth,
      nodeGap,
      align,
    })
  }, [box, nodes, links, nodeWidth, nodeGap, align])

  const selectLink = (link: SankeyChartLink | null) => {
    const id = link ? linkIdOf(link) : null
    if (selectedLinkId === undefined) setUncontrolledSelection(id)
    onSelectedLinkChange?.(id, link)
  }

  const linkEmphasis = (link: SankeyLayoutLink): SankeyEmphasis => {
    const id = linkIdOf(links[link.index])
    if (selection === id) return "active"
    if (hovered?.kind === "link") {
      return hovered.id === id ? "active" : "dim"
    }
    if (hovered?.kind === "node") {
      return link.source === hovered.id || link.target === hovered.id
        ? "active"
        : "dim"
    }
    return selection !== null && selection !== undefined ? "dim" : "rest"
  }

  const nodeEmphasis = (node: SankeyLayoutNode): SankeyEmphasis => {
    const engaged =
      hovered !== null || (selection !== null && selection !== undefined)
    if (!engaged) return "rest"
    if (hovered?.kind === "node" && hovered.id === node.id) return "active"
    const touched = layout?.links.some(
      (link) =>
        (link.source === node.id || link.target === node.id) &&
        linkEmphasis(link) === "active",
    )
    return touched ? "active" : "dim"
  }

  const defaultLinkLabel = (link: SankeyChartLink) => {
    const sourceLabel = nodeById.get(link.source)?.label ?? link.source
    const targetLabel = nodeById.get(link.target)?.label ?? link.target
    return `${sourceLabel} to ${targetLabel}, ${formatValue(link.value)}`
  }

  const nodeContext = (node: SankeyLayoutNode): SankeyChartNodeContext => ({
    node: nodeById.get(node.id)!,
    value: node.value,
    inValue: node.inValue,
    outValue: node.outValue,
    column: node.column,
    columnCount: layout!.columnCount,
    columnTotal: layout!.columnTotals[node.column],
  })

  const selectedLayoutLink = layout?.links.find(
    (link) => linkIdOf(links[link.index]) === selection,
  )

  return (
    <div
      data-slot="sankey-chart"
      className={cn(
        "relative flex h-full min-h-0 w-full min-w-0 font-sans text-foreground",
        className,
      )}
      onKeyDown={(event) => {
        if (event.key === "Escape" && selection != null) {
          event.stopPropagation()
          selectLink(null)
        }
      }}
      {...props}
    >
      <div
        ref={plotRef}
        className="mx-(--nessa-sankey-label-width) relative min-h-0 min-w-0 flex-1"
        style={
          {
            "--nessa-sankey-label-width": `${labelWidth > 0 ? labelWidth : 0}px`,
          } as React.CSSProperties
        }
      >
        {layout ? (
          <svg
            className="absolute inset-0 size-full overflow-visible"
            width={box!.width}
            height={box!.height}
            onPointerDown={(event) => {
              // A press on empty background clears the selection.
              if (event.target === event.currentTarget && selection != null) {
                selectLink(null)
              }
            }}
          >
            {layout.links.map((layoutLink) => {
              const link = links[layoutLink.index]
              const id = linkIdOf(link)
              const color = nodeById.get(link.source)?.color
              return (
                <path
                  key={id}
                  data-slot="sankey-chart-link"
                  data-link-id={id}
                  data-emphasis={linkEmphasis(layoutLink)}
                  role="button"
                  tabIndex={0}
                  aria-pressed={selection === id}
                  aria-label={(linkLabel ?? defaultLinkLabel)(link)}
                  d={sankeyRibbonPath(layoutLink, curvature)}
                  className={RIBBON_CLASSES}
                  style={
                    color
                      ? ({ "--nessa-sankey-color": color } as React.CSSProperties)
                      : undefined
                  }
                  onPointerEnter={() => setHovered({ kind: "link", id })}
                  onPointerLeave={() =>
                    setHovered((previous) =>
                      previous?.kind === "link" && previous.id === id
                        ? null
                        : previous,
                    )
                  }
                  onClick={() => selectLink(selection === id ? null : link)}
                  onKeyDown={(event) => {
                    if (event.key === "Enter" || event.key === " ") {
                      event.preventDefault()
                      selectLink(selection === id ? null : link)
                    }
                  }}
                />
              )
            })}
            {selectedLayoutLink ? (
              <path
                data-slot="sankey-chart-centerline"
                aria-hidden="true"
                d={sankeyCenterlinePath(selectedLayoutLink)}
                className="pointer-events-none fill-none stroke-[var(--nessa-sankey-color,var(--foreground))] stroke-2"
                strokeLinecap="round"
                style={
                  nodeById.get(selectedLayoutLink.source)?.color
                    ? ({
                        "--nessa-sankey-color": nodeById.get(
                          selectedLayoutLink.source,
                        )!.color,
                      } as React.CSSProperties)
                    : undefined
                }
              />
            ) : null}
            {layout.nodes.map((node) => (
              <rect
                key={node.id}
                data-slot="sankey-chart-node"
                data-node-id={node.id}
                data-emphasis={nodeEmphasis(node)}
                aria-hidden="true"
                x={node.x}
                y={node.y}
                width={node.width}
                height={Math.max(node.height, 1)}
                rx={Math.min(3, node.width / 2)}
                className={BAR_CLASSES}
                style={
                  nodeById.get(node.id)?.color
                    ? ({
                        "--nessa-sankey-color": nodeById.get(node.id)!.color,
                      } as React.CSSProperties)
                    : undefined
                }
                onPointerEnter={() =>
                  setHovered({ kind: "node", id: node.id })
                }
                onPointerLeave={() =>
                  setHovered((previous) =>
                    previous?.kind === "node" && previous.id === node.id
                      ? null
                      : previous,
                  )
                }
              />
            ))}
          </svg>
        ) : null}
        {layout && labelWidth > 0
          ? layout.nodes.map((node) => {
              const input = nodeById.get(node.id)!
              const context = nodeContext(node)
              const detail = renderNodeDetail
                ? renderNodeDetail(context)
                : formatValue(node.value)
              const first = node.column === 0
              const last = node.column === layout.columnCount - 1
              return (
                <div
                  key={node.id}
                  data-slot="sankey-chart-label"
                  data-emphasis={nodeEmphasis(node)}
                  className={cn(
                    LABEL_CLASSES,
                    first ? "items-end text-right" : "items-start text-left",
                  )}
                  style={{
                    top: node.y + Math.max(node.height, 1) / 2,
                    width: labelWidth - 8,
                    left: first
                      ? node.x - labelWidth
                      : node.x + node.width + 8,
                    // Middle-column labels overlay the ribbons to the
                    // right of their bar; only the outer columns get the
                    // reserved gutters.
                    maxWidth: first || last ? undefined : labelWidth - 8,
                  }}
                >
                  <span className="max-w-full truncate">
                    {input.label ?? input.id}
                  </span>
                  {detail == null ? null : (
                    <span className="nessa-text-2 max-w-full truncate">
                      {detail}
                    </span>
                  )}
                </div>
              )
            })
          : null}
      </div>
    </div>
  )
}

export { SankeyChart, linkIdOf as sankeyChartLinkId }

/** @responsibility Pure Sankey geometry: assigns nodes to columns, scales heights to flow values, stacks columns to fill the box, allocates link slots along each node, and draws ribbon paths. No React, no DOM. */

/** A flow endpoint supplied by the host. */
export interface SankeyNodeInput {
  /** Unique id links refer to. */
  id: string
}

/** A weighted flow between two nodes. */
export interface SankeyLinkInput {
  /** Id of the node the flow leaves. */
  source: string
  /** Id of the node the flow enters. */
  target: string
  /** Magnitude of the flow. Non-positive links are ignored. */
  value: number
}

/** How nodes without outgoing flow choose their column. */
export type SankeyAlign = "left" | "justify"

/** Inputs the layout is computed from. */
export interface SankeyLayoutOptions {
  nodes: readonly SankeyNodeInput[]
  links: readonly SankeyLinkInput[]
  /** Pixel width of the area the diagram fills. */
  width: number
  /** Pixel height of the area the diagram fills. */
  height: number
  /** Pixel width of each node bar. */
  nodeWidth: number
  /** Minimum vertical gap between stacked nodes in a column. */
  nodeGap: number
  /**
   * "justify" (default) pushes nodes without outgoing links into the last
   * column; "left" keeps every node at the earliest column its inputs allow.
   */
  align?: SankeyAlign
}

/** A positioned node bar. */
export interface SankeyLayoutNode {
  id: string
  /** Zero-based column, left to right. */
  column: number
  x: number
  y: number
  width: number
  height: number
  /** Flow through the node: max of incoming and outgoing sums. */
  value: number
  /** Sum of incoming link values. */
  inValue: number
  /** Sum of outgoing link values. */
  outValue: number
}

/** A positioned ribbon between two node bars. */
export interface SankeyLayoutLink {
  /** Index into the original `links` input. */
  index: number
  source: string
  target: string
  value: number
  /** Top edge of the ribbon where it leaves the source bar. */
  sourceY: number
  /** Top edge of the ribbon where it enters the target bar. */
  targetY: number
  /** Right edge of the source bar. */
  sourceX: number
  /** Left edge of the target bar. */
  targetX: number
  /** Ribbon thickness in pixels. */
  thickness: number
}

/** The computed diagram geometry. */
export interface SankeyLayout {
  nodes: SankeyLayoutNode[]
  links: SankeyLayoutLink[]
  columnCount: number
  /** Sum of node values per column, in column order. */
  columnTotals: number[]
}

interface NodeState {
  id: string
  order: number
  column: number
  inValue: number
  outValue: number
  value: number
}

/**
 * Longest-path column assignment over the link graph. Throws on links that
 * reference unknown nodes and on cycles — both are data errors a host must
 * fix, not states to render.
 */
function assignColumns(
  nodes: readonly SankeyNodeInput[],
  links: readonly SankeyLinkInput[],
): Map<string, number> {
  const known = new Set(nodes.map((node) => node.id))
  if (known.size !== nodes.length) {
    throw new Error("SankeyChart: duplicate node id")
  }
  const outgoing = new Map<string, string[]>()
  const indegree = new Map<string, number>()
  for (const node of nodes) {
    outgoing.set(node.id, [])
    indegree.set(node.id, 0)
  }
  for (const link of links) {
    if (!known.has(link.source) || !known.has(link.target)) {
      throw new Error(
        `SankeyChart: link ${link.source} → ${link.target} references an unknown node`,
      )
    }
    if (link.source === link.target) {
      throw new Error(`SankeyChart: link ${link.source} targets itself`)
    }
    if (link.value <= 0) continue
    outgoing.get(link.source)!.push(link.target)
    indegree.set(link.target, indegree.get(link.target)! + 1)
  }

  const columns = new Map<string, number>()
  const queue: string[] = []
  for (const node of nodes) {
    if (indegree.get(node.id) === 0) {
      columns.set(node.id, 0)
      queue.push(node.id)
    }
  }
  let visited = 0
  while (queue.length > 0) {
    const id = queue.shift()!
    visited += 1
    const depth = columns.get(id)!
    for (const next of outgoing.get(id)!) {
      columns.set(next, Math.max(columns.get(next) ?? 0, depth + 1))
      const remaining = indegree.get(next)! - 1
      indegree.set(next, remaining)
      if (remaining === 0) queue.push(next)
    }
  }
  if (visited !== nodes.length) {
    throw new Error("SankeyChart: the links form a cycle")
  }
  return columns
}

/**
 * Computes the full diagram geometry for one box size. Columns are spread
 * across the width; each column's node stack is scaled by the tightest
 * column and stretched vertically so every column fills the height, with
 * the slack shared evenly between its gaps.
 */
export function computeSankeyLayout(options: SankeyLayoutOptions): SankeyLayout {
  const { nodes, links, nodeWidth, nodeGap } = options
  const width = Math.max(options.width, nodeWidth)
  const height = Math.max(options.height, 0)
  const align = options.align ?? "justify"

  const columns = assignColumns(nodes, links)

  const states = new Map<string, NodeState>()
  nodes.forEach((node, order) => {
    states.set(node.id, {
      id: node.id,
      order,
      column: columns.get(node.id) ?? 0,
      inValue: 0,
      outValue: 0,
      value: 0,
    })
  })
  const activeLinks = links
    .map((link, index) => ({ ...link, index }))
    .filter((link) => link.value > 0)
  for (const link of activeLinks) {
    states.get(link.source)!.outValue += link.value
    states.get(link.target)!.inValue += link.value
  }
  for (const state of states.values()) {
    state.value = Math.max(state.inValue, state.outValue)
  }

  let columnCount = 0
  for (const state of states.values()) {
    columnCount = Math.max(columnCount, state.column + 1)
  }
  if (align === "justify" && columnCount > 1) {
    for (const state of states.values()) {
      if (state.outValue === 0) state.column = columnCount - 1
    }
  }

  const byColumn: NodeState[][] = Array.from({ length: columnCount }, () => [])
  for (const state of states.values()) {
    byColumn[state.column].push(state)
  }
  for (const column of byColumn) {
    column.sort((a, b) => a.order - b.order)
  }

  // The tightest column sets the value-to-pixel scale so every column fits.
  let scale = Infinity
  for (const column of byColumn) {
    const total = column.reduce((sum, node) => sum + node.value, 0)
    if (total <= 0) continue
    const available = height - nodeGap * (column.length - 1)
    scale = Math.min(scale, Math.max(available, 0) / total)
  }
  if (!Number.isFinite(scale)) scale = 0

  const columnGap =
    columnCount > 1 ? (width - nodeWidth * columnCount) / (columnCount - 1) : 0

  const positioned = new Map<string, SankeyLayoutNode>()
  const columnTotals: number[] = []
  byColumn.forEach((column, columnIndex) => {
    const total = column.reduce((sum, node) => sum + node.value, 0)
    columnTotals.push(total)
    const stack = total * scale
    // Share the leftover height evenly among the gaps so the column fills
    // the box; a lone node centers instead.
    const slack = Math.max(height - stack - nodeGap * (column.length - 1), 0)
    const gap =
      column.length > 1 ? nodeGap + slack / (column.length - 1) : nodeGap
    let y = column.length > 1 ? 0 : slack / 2
    const x = columnIndex * (nodeWidth + columnGap)
    for (const node of column) {
      const nodeHeight = node.value * scale
      positioned.set(node.id, {
        id: node.id,
        column: columnIndex,
        x,
        y,
        width: nodeWidth,
        height: nodeHeight,
        value: node.value,
        inValue: node.inValue,
        outValue: node.outValue,
      })
      y += nodeHeight + gap
    }
  })

  // Slot links along each bar, ordered by the counterpart bar's vertical
  // position so ribbons fan out without gratuitous crossings.
  const outCursor = new Map<string, number>()
  const inCursor = new Map<string, number>()
  const bySourceOrder = [...activeLinks].sort((a, b) => {
    const ay = positioned.get(a.target)!.y - positioned.get(b.target)!.y
    return ay !== 0 ? ay : a.index - b.index
  })
  const sourceY = new Map<number, number>()
  for (const link of bySourceOrder) {
    const bar = positioned.get(link.source)!
    const offset = outCursor.get(link.source) ?? 0
    sourceY.set(link.index, bar.y + offset)
    outCursor.set(link.source, offset + link.value * scale)
  }
  const byTargetOrder = [...activeLinks].sort((a, b) => {
    const ay = positioned.get(a.source)!.y - positioned.get(b.source)!.y
    return ay !== 0 ? ay : a.index - b.index
  })
  const targetY = new Map<number, number>()
  for (const link of byTargetOrder) {
    const bar = positioned.get(link.target)!
    const offset = inCursor.get(link.target) ?? 0
    targetY.set(link.index, bar.y + offset)
    inCursor.set(link.target, offset + link.value * scale)
  }

  const layoutLinks: SankeyLayoutLink[] = activeLinks.map((link) => {
    const source = positioned.get(link.source)!
    const target = positioned.get(link.target)!
    return {
      index: link.index,
      source: link.source,
      target: link.target,
      value: link.value,
      sourceY: sourceY.get(link.index)!,
      targetY: targetY.get(link.index)!,
      sourceX: source.x + source.width,
      targetX: target.x,
      thickness: link.value * scale,
    }
  })

  return {
    nodes: [...positioned.values()],
    links: layoutLinks,
    columnCount,
    columnTotals,
  }
}

/**
 * SVG path for a link's filled ribbon. `curvature` in [0, 1] moves the
 * bezier control points from the bar edges (0, straight taper) toward the
 * horizontal midpoint (1, the classic S curve).
 */
export function sankeyRibbonPath(
  link: SankeyLayoutLink,
  curvature: number,
): string {
  const { sourceX, targetX, sourceY, targetY } = link
  // Ribbons thinner than a hairline stay visible.
  const thickness = Math.max(link.thickness, 1)
  const c0 = sourceX + (targetX - sourceX) * 0.5 * curvature
  const c1 = targetX - (targetX - sourceX) * 0.5 * curvature
  const s0 = sourceY
  const s1 = sourceY + thickness
  const t0 = targetY
  const t1 = targetY + thickness
  return [
    `M ${sourceX} ${s0}`,
    `C ${c0} ${s0} ${c1} ${t0} ${targetX} ${t0}`,
    `L ${targetX} ${t1}`,
    `C ${c1} ${t1} ${c0} ${s1} ${sourceX} ${s1}`,
    "Z",
  ].join(" ")
}

/**
 * SVG path for the ribbon's center line — the emphasis stroke drawn along a
 * selected link.
 */
export function sankeyCenterlinePath(link: SankeyLayoutLink): string {
  const { sourceX, targetX, sourceY, targetY } = link
  const thickness = Math.max(link.thickness, 1)
  const mid = (sourceX + targetX) / 2
  const s = sourceY + thickness / 2
  const t = targetY + thickness / 2
  return `M ${sourceX} ${s} C ${mid} ${s} ${mid} ${t} ${targetX} ${t}`
}
